def add_mirror(req: MirrorRequest):
    return {"path": create_mirror(req.url, req.name)}

# mirror/service.py:9-12  create_mirror
def create_mirror(url: str, name: str) -> str:
    dest = MIRRORS / name
    Repo.clone_from(url, dest, mirror=True)
    return str(dest)
